import{_ as i,o as e,c as a,al as t}from"./chunks/framework.V8HPfhr5.js";const p="/JustPIC.jl/dev/assets/temperature_flip.Ca1GOoPW.png",g=JSON.parse('{"title":"PIC/FLIP temperature update in 2D","description":"","frontmatter":{},"headers":[],"relativePath":"temperature_flip.md","filePath":"temperature_flip.md","lastUpdated":null}'),n={name:"temperature_flip.md"};function l(h,s,r,d,o,c){return e(),a("div",null,[...s[0]||(s[0]=[t(`<h1 id="PIC/FLIP-temperature-update-in-2D" tabindex="-1">PIC/FLIP temperature update in 2D <a class="header-anchor" href="#PIC/FLIP-temperature-update-in-2D" aria-label="Permalink to &quot;PIC/FLIP temperature update in 2D {#PIC/FLIP-temperature-update-in-2D}&quot;">​</a></h1><p>The script <a href="https://github.com/JuliaGeodynamics/JustPIC.jl/blob/main/scripts/temperature_advection_flip.jl" target="_blank" rel="noreferrer"><code>scripts/temperature_advection_flip.jl</code></a> carries a temperature blob through a cellular flow and applies a grid-side update (explicit diffusion) to it, once with FLIP and once with PIC. The update is passed to the particles as an increment and brought back to the grid as the average particle increment. See <a href="./pic_flip">PIC/FLIP</a> for the functions involved.</p><p>Particles and the temperature <code>T</code> (at the ghosted centroids) are set up as in <a href="./field_advection2D">Field advection in 2D</a>. Besides the particle temperature <code>pT</code>, a second particle field <code>pT0</code> stores its value before each update:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">particle_args </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pT, pT0 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> init_cell_arrays</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(particles, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Val</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">))</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">centroid2particle!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(pT, T, particles)</span></span></code></pre></div><p>Each time step first advects the particles and builds <code>T</code> from them:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">advection!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(particles, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">RungeKutta2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(), V, dt)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">move_particles!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(particles, particle_args)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">inject_particles!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(particles, (pT,))</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">particle2centroid!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(T, pT, particles)</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">neumann!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(T)</span></span></code></pre></div><p><code>particle2centroid!</code> fills only the interior of <code>T</code>. The FLIP transfer below reads the ghost centroids of both <code>T</code> and the updated copy, so their ghost layers must be consistent. Here both use zero-flux copies from the first physical centroid (<code>neumann!</code>).</p><p>The three transfers that follow are the whole method:</p><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 1. grid-side update on a copy of T</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Tg .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> T</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">diffuse!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Tg, κ, dt, dx, dy)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 2. grid → particles: pT += interpolated (Tg - T)   (α = 0: pure FLIP)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pT0</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">.</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">data</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">centroid2particle_flip!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(pT, Tg, T, particles; α)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 3. particles → grid: T += Σω (pT - pT0) / Σω</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">particle2centroid_flip!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(T, pT, pT0, particles)</span></span></code></pre></div><p>After step 3, <code>T</code> equals the grid-side result <code>Tg</code> up to the interpolation error of the two transfers. The script carries two copies of the field on the same particles and flow: a FLIP copy (<code>α = 0</code>) and a PIC copy (<code>α = 1</code>), each with its own particle fields. After 100 steps the FLIP copy still peaks at about <code>0.75</code> and stays within <code>5e-4</code> of the grid update (relative norm). The PIC copy peaks at about <code>0.39</code> and differs from the grid update by about <code>5e-3</code>: every step replaces the particle values by an average over the grid, which smooths the blob much more than the physical diffusion does. Both rows use the same color scales:</p><p><img src="`+p+'" alt=""></p><p>Cells without particles are left untouched by <code>particle2centroid_flip!</code>, and intermediate <code>α</code> blends the two behaviors, damping FLIP noise at the cost of some extra diffusion.</p><p>To run the example (it saves figures to <code>figs/</code>):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">julia</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --project=.</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/temperature_advection_flip.jl</span></span></code></pre></div>',14)])])}const u=i(n,[["render",l]]);export{g as __pageData,u as default};
